SOURCE_FORMS = {
    "amaze": "amazed", "give A a ride": "give her a ride", "come alive": "comes alive",
    "take after": "takes after", "die out": "died out", "rehearsal": "rehearsals",
    "decoration": "decorations", "antler": "antlers", "crash": "crashes", "vehicle": "vehicle's",
    "reflect": "reflecting", "inspire": "inspired", "publish": "published",
    "combine": "combines", "advantage": "advantages", "celebrity": "celebrities",
}


def vocabulary():
    result = []
    for n, (word, meaning, pos, example, distractors) in enumerate(WORDS, 1):
        result.append(dict(word=word, meaning=meaning, pos=pos, level="準2級プラス",
                           source="大問1" if n <= 25 else "大問2" if n <= 40 else "大問3",
                           sourceForm=SOURCE_FORMS.get(word, word), example=example,
                           distractors=distractors.split("／")))
    return result


def example(en, ja, note):
    return dict(en=en, ja=ja, note=note)


